select jsonb_build_object('checkedAt',now(),'columns',(select jsonb_agg(to_jsonb(c) order by table_name,ordinal_position) from (select c.table_name,c.column_name,c.data_type,c.is_nullable,c.column_default,c.ordinal_position,pg_catalog.format_type(a.atttypid,a.atttypmod) as physical_type from information_schema.columns c join pg_class pc on pc.relname=c.table_name join pg_namespace n on n.oid=pc.relnamespace and n.nspname=c.table_schema join pg_attribute a on a.attrelid=pc.oid and a.attname=c.column_name where c.table_schema='public' and c.table_name in ('pick2_feature_snapshots','pick2_mlb_team_daily_features','pick2_mlb_pitcher_daily_features','pick2_mlb_bullpen_daily_features','pick2_mlb_batter_daily_features','pick2_mlb_matchup_daily_features','pick2_mlb_first_inning_daily_features','pick2_game_predictions','pick2_mlb_market_event_mappings','pick2_mlb_market_price_observations','pick2_mlb_market_value_evaluations','pick2_mlb_official_picks','pick2_mlb_games','pick2_mlb_players','sports_teams','pick2_raw_mlb_statcast_pitches')) c),'indexes',(select jsonb_agg(to_jsonb(i) order by table_name,index_name) from (select t.relname as table_name, x.relname as index_name,i.indisunique,i.indisvalid,pg_get_indexdef(i.indexrelid) as definition from pg_index i join pg_class t on t.oid=i.indrelid join pg_namespace n on n.oid=t.relnamespace join pg_class x on x.oid=i.indexrelid where n.nspname='public' and t.relname in ('pick2_feature_snapshots','pick2_mlb_team_daily_features','pick2_mlb_pitcher_daily_features','pick2_mlb_bullpen_daily_features','pick2_mlb_batter_daily_features','pick2_mlb_matchup_daily_features','pick2_mlb_first_inning_daily_features','pick2_game_predictions','pick2_mlb_market_event_mappings','pick2_mlb_market_price_observations','pick2_mlb_market_value_evaluations','pick2_mlb_official_picks','pick2_mlb_games','pick2_mlb_players','sports_teams','pick2_raw_mlb_statcast_pitches'))i),'constraints',(select jsonb_agg(to_jsonb(c) order by table_name,conname) from (select t.relname as table_name,c.conname,c.contype,c.convalidated,pg_get_constraintdef(c.oid) as definition from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname in ('pick2_feature_snapshots','pick2_mlb_team_daily_features','pick2_mlb_pitcher_daily_features','pick2_mlb_bullpen_daily_features','pick2_mlb_batter_daily_features','pick2_mlb_matchup_daily_features','pick2_mlb_first_inning_daily_features','pick2_game_predictions','pick2_mlb_market_event_mappings','pick2_mlb_market_price_observations','pick2_mlb_market_value_evaluations','pick2_mlb_official_picks','pick2_mlb_games','pick2_mlb_players','sports_teams','pick2_raw_mlb_statcast_pitches'))c),'integrity',(select jsonb_agg(to_jsonb(x)) from (select 'pick2_mlb_team_daily_features' as table_name, count(*) as rows, count(*) filter (where d.feature_snapshot_id is not null and s.id is null) as orphans from public.pick2_mlb_team_daily_features d left join public.pick2_feature_snapshots s on s.id=d.feature_snapshot_id union all select 'pick2_mlb_pitcher_daily_features' as table_name, count(*) as rows, count(*) filter (where d.feature_snapshot_id is not null and s.id is null) as orphans from public.pick2_mlb_pitcher_daily_features d left join public.pick2_feature_snapshots s on s.id=d.feature_snapshot_id union all select 'pick2_mlb_bullpen_daily_features' as table_name, count(*) as rows, count(*) filter (where d.feature_snapshot_id is not null and s.id is null) as orphans from public.pick2_mlb_bullpen_daily_features d left join public.pick2_feature_snapshots s on s.id=d.feature_snapshot_id union all select 'pick2_mlb_batter_daily_features' as table_name, count(*) as rows, count(*) filter (where d.feature_snapshot_id is not null and s.id is null) as orphans from public.pick2_mlb_batter_daily_features d left join public.pick2_feature_snapshots s on s.id=d.feature_snapshot_id union all select 'pick2_mlb_matchup_daily_features' as table_name, count(*) as rows, count(*) filter (where d.feature_snapshot_id is not null and s.id is null) as orphans from public.pick2_mlb_matchup_daily_features d left join public.pick2_feature_snapshots s on s.id=d.feature_snapshot_id union all select 'pick2_mlb_first_inning_daily_features' as table_name, count(*) as rows, count(*) filter (where d.feature_snapshot_id is not null and s.id is null) as orphans from public.pick2_mlb_first_inning_daily_features d left join public.pick2_feature_snapshots s on s.id=d.feature_snapshot_id)x),'historicalChecks',(select jsonb_agg(to_jsonb(h)) from (select 'pick2_feature_snapshots' as table_name,count(*) as violating_rows from public.pick2_feature_snapshots where mlbam_batter_id <= 0 or mlbam_person_id <= 0 or mlbam_pitcher_id <= 0 or target_game_pk <= 0 union all select 'pick2_game_predictions' as table_name,count(*) as violating_rows from public.pick2_game_predictions where game_pk <= 0 union all select 'pick2_mlb_batter_daily_features' as table_name,count(*) as violating_rows from public.pick2_mlb_batter_daily_features where mlbam_batter_id <= 0 or target_game_pk <= 0 union all select 'pick2_mlb_bullpen_daily_features' as table_name,count(*) as violating_rows from public.pick2_mlb_bullpen_daily_features where target_game_pk <= 0 union all select 'pick2_mlb_first_inning_daily_features' as table_name,count(*) as violating_rows from public.pick2_mlb_first_inning_daily_features where away_starter_mlbam_pitcher_id <= 0 or home_starter_mlbam_pitcher_id <= 0 or target_game_pk <= 0 union all select 'pick2_mlb_matchup_daily_features' as table_name,count(*) as violating_rows from public.pick2_mlb_matchup_daily_features where mlbam_batter_id <= 0 or mlbam_pitcher_id <= 0 or target_game_pk <= 0 union all select 'pick2_mlb_pitcher_daily_features' as table_name,count(*) as violating_rows from public.pick2_mlb_pitcher_daily_features where mlbam_pitcher_id <= 0 or target_game_pk <= 0 union all select 'pick2_mlb_team_daily_features' as table_name,count(*) as violating_rows from public.pick2_mlb_team_daily_features where target_game_pk <= 0 union all select 'pick2_raw_mlb_statcast_pitches' as table_name,count(*) as violating_rows from public.pick2_raw_mlb_statcast_pitches where mlbam_batter_id <= 0 or mlbam_pitcher_id <= 0)h)) as evidence;
